import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Creating a VS Code extension","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/creating-an-extension.md"},"headers":[],"relativePath":"guides/creating-an-extension.md","filePath":"docs/creating-an-extension.md","lastUpdated":1792029789000}`),a={name:`guides/creating-an-extension.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="creating-a-vs-code-extension" tabindex="-1">Creating a VS Code extension <a class="header-anchor" href="#creating-a-vs-code-extension" aria-label="Permalink to “Creating a VS Code extension”">​</a></h1><p>Create an extension package with the Turbo generator:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen:extension</span></span></code></pre></div><p>Enter a kebab-case folder name, a display name, and a short description. The generator scaffolds a TypeScript VS Code extension in <code>extensions/</code>, registers its independent Release Please component, installs workspace dependencies, and refreshes the generated README catalog. Extension packages are private workspace packages; releases are distributed as VSIX assets on GitHub Releases.</p><p>Each extension supplies <code>build</code>, <code>typecheck</code>, <code>test</code>, and <code>package</code> scripts. The package script uses <code>@vscode/vsce</code> to create a VSIX without installing npm dependencies, so bundle production code into <code>dist/</code> during the build. If the extension ships generated data from a workspace package, list that package in <code>pumpkinBundleDependencies</code>; Release Please includes its changes in the extension release.</p><h2 id="build-and-package" tabindex="-1">Build and package <a class="header-anchor" href="#build-and-package" aria-label="Permalink to “Build and package”">​</a></h2><p>From the repository root, run the extension&#39;s build and package scripts. For Minecraft Terms:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minecraft-terms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minecraft-terms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span></span></code></pre></div><p>The package command writes <code>minecraft-terms-&lt;version&gt;.vsix</code> into <code>extensions/minecraft-terms/</code>. For another extension, replace <code>minecraft-terms</code> with its package name.</p><p>CI sends changed extension packages through <code>.github/workflows/extensions.yml</code> only; an extension-only change does not run the plugin build or Pumpkin integration suites. Mixed changes run the extension checks and the checks for every other changed area.</p><p>The root README lists extensions in its generated catalog, and each extension README includes a generated link to its API reference. The documentation site publishes API references generated from extension source; it does not publish extension README pages. Add the extension description and license to its <code>package.json</code>; <code>pnpm readme</code> refreshes the catalog and API-reference links. Release Please updates the extension version and changelog, and the release workflow packages the tagged revision and attaches the VSIX to its release.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};